const now = new Date(
  new Date().toLocaleString("en-US", {
    timeZone: "Asia/Kolkata"
  })
);

const hour = now.getHours();

let subject = "";
let message = "";

// Morning
if (hour === 7) {
  subject = "Good Morning ❤️";
  message = "Good morning ❤️\nHave a beautiful day!";
}

// Breakfast
else if (hour === 9) {
  subject = "Breakfast Time 🍳";
  message = "Hey ❤️\nHad breakfast?";
}

// Lunch
else if (hour === 13) {
  subject = "Lunch Time 🍴";
  message = "Did you eat lunch? ❤️";
}

// Snacks
else if (hour === 16) {
  subject = "Snacks Time ☕";
  message = "Had snacks? 😄";
}

// Evening
else if (hour === 18) {
  subject = "Evening Check 🌇";
  message = "What are you doing now? ❤️";
}

// Dinner
else if (hour === 21) {
  subject = "Dinner Time 🍽️";
  message = "Had dinner? Take care ❤️";
}

// Good Night
else if (hour === 23) {
  subject = "Good Night 🌙";
  message = "Good night ❤️\nSleep well and sweet dreams!";
}

// Stop workflow if current hour doesn't match
if (message === "") {
  return [];
}

// Return data to Gmail node
return [
  {
    json: {
      subject,
      message,
      hour
    }
  }
];
